import json

def convert_currency(amount, rate):
    return round(amount * rate, 2)

def word_count(text):
    return len(text.split())

registry = {"convert_currency": convert_currency, "word_count": word_count}

model_output = '[{"name": "convert_currency", "args": {"amount": 120, "rate": 0.012}},' \
               ' {"name": "word_count", "args": {"text": "tools turn talk into action"}},' \
               ' {"name": "launch_rocket", "args": {}}]'

results = []
for call in json.loads(model_output):
    fn = registry.get(call["name"])
    if fn is None:
        results.append({"tool": call["name"], "error": "unknown tool"})
        continue
    results.append({"tool": call["name"], "result": fn(**call["args"])})
print(results)
